SELECT COUNT(dp.id) FROM doctor_price dp JOIN doctor d ON dp.doctor_id = d.id LEFT JOIN medical_dept_sub_doctor mdsd ON mdsd.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mdsd.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE 1 = 1
AND d.name LIKE CONCAT('%', #{name}, '%')
AND md.id = #{deptId}
AND d.job = #{job}
AND d.status = #{status}

SELECT d.name AS doctorName, d.sex AS sex, d.job AS job, md.name AS deptName, mds.name AS deptSubName, dp.price_1 AS price_1, dp.doctor_id AS doctorId, dp.id AS id, dp.level AS level FROM doctor_price dp JOIN doctor d ON dp.doctor_id = d.id LEFT JOIN medical_dept_sub_doctor mdsd ON mdsd.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mdsd.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE 1 = 1
AND d.name LIKE CONCAT('%', #{name}, '%')
AND md.id = #{deptId}
AND d.job = #{job}
AND d.status = #{status}
ORDER BY md.id ${order}
LIMIT #{length} OFFSET #{start}

mapper.update:
UPDATE doctor_price
SET price_1 = #{price_1},
    level = #{level}
WHERE id = #{id}

